package io.github.abdellahjebar.paraphe.documents.port;

import io.github.abdellahjebar.paraphe.documents.domain.StoredFile;
import java.io.IOException;
import java.io.InputStream;

/**
 * Where uploaded files live. Keys are opaque and generated by the storage: callers never choose a
 * path, so a file name can never escape the storage.
 */
public interface FileStorage {

    /**
     * Stores the content and returns its key, size and SHA-256.
     *
     * @throws io.github.abdellahjebar.paraphe.documents.domain.FileTooLargeException when the
     *     content exceeds {@code maxBytes}; nothing is kept in that case
     */
    StoredFile store(InputStream content, long maxBytes) throws IOException;

    InputStream open(String key) throws IOException;

    /** Removes a file; unknown keys are ignored. */
    void delete(String key) throws IOException;
}
